import copy, re, zipfile, shutil, os
from lxml import etree
WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
W="{%s}"%WNS
XMLSP="{http://www.w3.org/XML/1998/namespace}space"

class Doc:
    def __init__(self, path):
        self.path=path
        self.z=zipfile.ZipFile(path)
        self.tree=etree.fromstring(self.z.read("word/document.xml"))
        self.body=self.tree.find(W+"body")
    def paras(self):
        return [c for c in self.body if c.tag==W+"p"]
    def find(self, sub, start=0, exact=False):
        hits=[p for p in self.paras() if (ptext(p)==sub if exact else sub in ptext(p))]
        if len(hits)!=1:
            raise Exception("find %r -> %d hits"%(sub,len(hits)))
        return hits[0]
    def save(self, out, extra=None):
        extra=extra or {}
        zo=zipfile.ZipFile(out,"w",zipfile.ZIP_DEFLATED)
        names=self.z.namelist()
        for n in names:
            if n=="word/document.xml":
                zo.writestr(n, etree.tostring(self.tree, xml_declaration=True, encoding="UTF-8", standalone=True))
            elif n in extra:
                zo.writestr(n, extra[n])
            else:
                zo.writestr(n, self.z.read(n))
        for n,v in extra.items():
            if n not in names: zo.writestr(n,v)
        zo.close()

def ptext(p):
    out=[]
    for el in p.iter(W+"t", W+"delText"):
        out.append(el.text or "")
    return "".join(out)

def accept_all(body):
    for d in list(body.iter(W+"del")):
        par=d.getparent()
        if par.tag==W+"rPr":  # paragraph mark deletion -> not present here
            par.remove(d); continue
        par.remove(d)
    for i in list(body.iter(W+"ins")):
        par=i.getparent()
        if par.tag==W+"rPr":
            par.remove(i); continue
        idx=par.index(i)
        for k,ch in enumerate(list(i)):
            par.insert(idx+k, ch)
        par.remove(i)
    # strip szCs noise
    for s in list(body.iter(W+"szCs")):
        s.getparent().remove(s)

def runs(p):
    return [c for c in p if c.tag==W+"r" and c.find(W+"t") is not None]

def mkrun(rpr, text, bold=None, italic=None):
    r=etree.Element(W+"r")
    if rpr is not None:
        rp=copy.deepcopy(rpr)
    else:
        rp=etree.Element(W+"rPr")
    if bold is True and rp.find(W+"b") is None:
        # insert b after rFonts
        b=etree.Element(W+"b"); rf=rp.find(W+"rFonts")
        if rf is not None: rf.addnext(b)
        else: rp.insert(0,b)
    if bold is False:
        for b in rp.findall(W+"b"): rp.remove(b)
    if italic is True and rp.find(W+"i") is None:
        i=etree.Element(W+"i"); bb=rp.find(W+"b"); rf=rp.find(W+"rFonts")
        (bb if bb is not None else rf).addnext(i) if (bb is not None or rf is not None) else rp.insert(0,i)
    if italic is False:
        for i in rp.findall(W+"i"): rp.remove(i)
    r.append(rp)
    t=etree.SubElement(r, W+"t"); t.set(XMLSP,"preserve"); t.text=text
    return r

def parse_markup(s):
    """**bold**, *italic* -> list of (text,bold,italic)"""
    segs=[]
    pos=0
    for m in re.finditer(r"\*\*(.+?)\*\*|\*(.+?)\*", s):
        if m.start()>pos: segs.append((s[pos:m.start()],None,None))
        if m.group(1) is not None: segs.append((m.group(1),True,None))
        else: segs.append((m.group(2),None,True))
        pos=m.end()
    if pos<len(s): segs.append((s[pos:],None,None))
    return segs

def replace(p, old, new, occurrence=0, base_bold=None):
    """untracked replacement of text old with markup new inside paragraph p"""
    rs=runs(p)
    texts=[r.find(W+"t").text or "" for r in rs]
    full="".join(texts)
    idx=-1; start=0
    for k in range(occurrence+1):
        idx=full.find(old, start)
        if idx<0: raise Exception("replace: %r not in %r"%(old, full[:120]))
        start=idx+1
    if full.find(old, idx+1)>=0 and occurrence==0:
        raise Exception("replace: ambiguous %r"%old)
    end=idx+len(old)
    # locate runs
    off=0; sr=er=None
    for k,tx in enumerate(texts):
        if sr is None and idx < off+len(tx) or (sr is None and idx==off+len(tx) and k==len(texts)-1):
            sr=k; so=idx-off
        if er is None and end <= off+len(tx):
            er=k; eo=end-off
        off+=len(tx)
    if sr is None: sr=len(texts)-1; so=len(texts[-1])
    if er is None: er=len(texts)-1; eo=len(texts[-1])
    srun=rs[sr]; rpr=srun.find(W+"rPr")
    before=texts[sr][:so]; after=texts[er][eo:]
    erpr=rs[er].find(W+"rPr")
    anchor_idx=p.index(srun)
    for k in range(sr, er+1):
        p.remove(rs[k])
    newruns=[]
    if before: newruns.append(mkrun(rpr,before))
    for (tx,b,i) in parse_markup(new):
        if base_bold is not None and b is None: b=base_bold
        newruns.append(mkrun(rpr,tx,bold=b,italic=i))
    if after: newruns.append(mkrun(erpr,after))
    for k,r in enumerate(newruns):
        p.insert(anchor_idx+k, r)

def set_text(p, new, base_bold=None):
    replace(p, ptext(p), new, base_bold=base_bold)

def clone_para(template, markup, rpr_from="last", base_bold=None):
    np_=etree.Element(W+"p")
    ppr=template.find(W+"pPr")
    if ppr is not None: np_.append(copy.deepcopy(ppr))
    rs=runs(template)
    rpr=None
    if rs:
        src=rs[-1] if rpr_from=="last" else rs[0]
        rpr=src.find(W+"rPr")
    for (tx,b,i) in parse_markup(markup):
        if base_bold is not None and b is None: b=base_bold
        np_.append(mkrun(rpr,tx,bold=b,italic=i))
    return np_

def remove_para(p):
    p.getparent().remove(p)
