import copy, re
from difflib import SequenceMatcher
from lxml import etree
from rl import W, XMLSP, ptext, runs

class Rev:
    def __init__(self, author, date, start=100):
        self.author=author; self.date=date; self.n=start
    def el(self, tag):
        e=etree.Element(W+tag)
        e.set(W+"id", str(self.n)); self.n+=1
        e.set(W+"author", self.author); e.set(W+"date", self.date)
        return e

TOK=re.compile(r"\w+|\s+|[^\w\s]")
def tokens(p):
    out=[]
    for r in runs(p):
        rpr=r.find(W+"rPr")
        key=etree.tostring(rpr) if rpr is not None else b""
        for m in TOK.finditer(r.find(W+"t").text or ""):
            out.append((m.group(0), key, rpr))
    return out

def mk(rpr, text, deleted=False):
    r=etree.Element(W+"r")
    if rpr is not None: r.append(copy.deepcopy(rpr))
    t=etree.SubElement(r, W+("delText" if deleted else "t")); t.set(XMLSP,"preserve"); t.text=text
    return r

def group(toks):
    """group consecutive tokens with same rPr key"""
    out=[]
    for tx,key,rpr in toks:
        if out and out[-1][1]==key: out[-1][0]+=tx
        else: out.append([tx,key,rpr])
    return out

def mark_ppr(p, rev, kind):
    ppr=p.find(W+"pPr")
    if ppr is None:
        ppr=etree.Element(W+"pPr"); p.insert(0,ppr)
    rpr=ppr.find(W+"rPr")
    if rpr is None:
        rpr=etree.SubElement(ppr, W+"rPr")
    rpr.insert(0, rev.el(kind))

def ins_para(bp, rev):
    p=copy.deepcopy(bp)
    for r in [c for c in p if c.tag==W+"r"]:
        i=rev.el("ins"); r.addprevious(i); i.append(r)
    mark_ppr(p, rev, "ins")
    return p

def del_para(ap, rev):
    p=copy.deepcopy(ap)
    for r in [c for c in p if c.tag==W+"r"]:
        for t in r.findall(W+"t"): t.tag=W+"delText"
        d=rev.el("del"); r.addprevious(d); d.append(r)
    mark_ppr(p, rev, "del")
    return p

def diff_para(ap, bp, rev):
    a=tokens(ap); b=tokens(bp)
    sm=SequenceMatcher(None, [x[0] for x in a], [x[0] for x in b], autojunk=False)
    ops=[list(o) for o in sm.get_opcodes()]
    # cleanup: absorb short equal segments between changes
    changed=True
    while changed:
        changed=False
        for k in range(1,len(ops)-1):
            tag,i1,i2,j1,j2=ops[k]
            if tag=="equal" and ops[k-1][0]!="equal" and ops[k+1][0]!="equal":
                seg="".join(x[0] for x in a[i1:i2])
                if len(seg.strip())<=3 or (i2-i1)<=2:
                    ops[k][0]="replace"; changed=True
        # merge adjacent non-equal
        merged=[]
        for o in ops:
            if merged and o[0]!="equal" and merged[-1][0]!="equal":
                merged[-1]=["replace", merged[-1][1], o[2], merged[-1][3], o[4]]
            else: merged.append(o)
        if len(merged)!=len(ops): changed=True
        ops=merged
    p=etree.Element(W+"p")
    ppr=ap.find(W+"pPr")
    if ppr is not None: p.append(copy.deepcopy(ppr))
    for tag,i1,i2,j1,j2 in ops:
        if tag=="equal":
            for tx,key,rpr in group(a[i1:i2]): p.append(mk(rpr,tx))
        else:
            if i2>i1:
                d=rev.el("del")
                for tx,key,rpr in group(a[i1:i2]): d.append(mk(rpr,tx,True))
                p.append(d)
            if j2>j1:
                i=rev.el("ins")
                for tx,key,rpr in group(b[j1:j2]): i.append(mk(rpr,tx))
                p.append(i)
    return p

def ratio(x,y):
    return SequenceMatcher(None, x, y, autojunk=False).ratio()

def align_block(A, B, thr=0.45):
    """DP alignment maximizing sum of ratios; returns list of (i or None, j or None)"""
    n,m=len(A),len(B)
    R=[[ratio(ptext(A[i]),ptext(B[j])) for j in range(m)] for i in range(n)]
    S=[[0.0]*(m+1) for _ in range(n+1)]; bt=[[None]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        for j in range(m+1):
            if i==0 and j==0: continue
            best=-1; arg=None
            if i>0 and S[i-1][j]>best: best=S[i-1][j]; arg="d"
            if j>0 and S[i][j-1]>best: best=S[i][j-1]; arg="i"
            if i>0 and j>0 and R[i-1][j-1]>=thr and S[i-1][j-1]+R[i-1][j-1]>best:
                best=S[i-1][j-1]+R[i-1][j-1]; arg="m"
            S[i][j]=best; bt[i][j]=arg
    out=[]; i,j=n,m
    while i>0 or j>0:
        a=bt[i][j]
        if a=="m": out.append((i-1,j-1)); i-=1; j-=1
        elif a=="d": out.append((i-1,None)); i-=1
        else: out.append((None,j-1)); j-=1
    return out[::-1]

def compare(base_doc, new_doc, rev):
    A=base_doc.paras(); B=new_doc.paras()
    sm=SequenceMatcher(None, [ptext(p) for p in A], [ptext(p) for p in B], autojunk=False)
    out=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=="equal":
            out+= [copy.deepcopy(p) for p in A[i1:i2]]
        else:
            for ia,jb in align_block(A[i1:i2], B[j1:j2]):
                if ia is not None and jb is not None: out.append(diff_para(A[i1+ia], B[j1+jb], rev))
                elif ia is not None: out.append(del_para(A[i1+ia], rev))
                else: out.append(ins_para(B[j1+jb], rev))
    body=base_doc.body
    sect=body.find(W+"sectPr")
    for c in list(body):
        if c.tag==W+"p": body.remove(c)
    for p in out:
        sect.addprevious(p)
    return base_doc
